import { HttpError } from "wasp/server";
import type { GetAnalytics } from "wasp/server/operations";

type Resolution = "day" | "week" | "month";

type GetAnalyticsInput = {
  startDate: string;
  endDate: string;
  resolution: Resolution;
};

type TimeSeriesPoint = {
  date: string;
  income: number;
  expense: number;
  net: number;
};

type CategoryBreakdownPoint = {
  category: string;
  amount: number;
  type: "INCOME" | "EXPENSE";
};

type GetAnalyticsOutput = {
  timeSeries: TimeSeriesPoint[];
  categoryBreakdown: CategoryBreakdownPoint[];
  summary: {
    totalIncome: number;
    totalExpense: number;
    netSavings: number;
    savingsRate: number;
  };
};

// SQLite expressions used to bucket a `date` column into the period string
// that identifies the aggregation bucket for the given resolution.
const PERIOD_EXPRESSIONS: Record<Resolution, string> = {
  day: "strftime('%Y-%m-%d', date)",
  month: "strftime('%Y-%m', date)",
  // ISO-8601 week ("YYYY-Www"): shift the date to the Thursday of its ISO
  // week (the well-known SQLite trick for ISO week calculations), then read
  // the ISO year off that Thursday and derive the week number from its
  // day-of-year.
  week:
    "(strftime('%Y', date, '-3 days', 'weekday 4') || '-W' || " +
    "substr('0' || ((CAST(strftime('%j', date, '-3 days', 'weekday 4') AS INTEGER) - 1) / 7 + 1), -2, 2))",
};

export const getAnalytics: GetAnalytics<
  GetAnalyticsInput,
  GetAnalyticsOutput
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const { startDate, endDate, resolution } = args;

  const periodExpr = PERIOD_EXPRESSIONS[resolution];
  if (!periodExpr) {
    throw new HttpError(400, "Invalid resolution");
  }

  const userId = context.user.id;

  const rawTimeSeries = await context.entities.Transaction.$queryRawUnsafe<
    Array<{ period: string; income: number | null; expense: number | null }>
  >(
    `SELECT ${periodExpr} as period,
            SUM(CASE WHEN type = 'INCOME' THEN amount ELSE 0 END) as income,
            SUM(CASE WHEN type = 'EXPENSE' THEN amount ELSE 0 END) as expense
     FROM "Transaction"
     WHERE userId = ? AND date(date) >= date(?) AND date(date) <= date(?)
     GROUP BY period
     ORDER BY period ASC`,
    userId,
    startDate,
    endDate
  );

  const timeSeries: TimeSeriesPoint[] = rawTimeSeries.map((row) => {
    const income = Number(row.income) || 0;
    const expense = Number(row.expense) || 0;
    return {
      date: row.period,
      income,
      expense,
      net: income - expense,
    };
  });

  const rawCategoryBreakdown = await context.entities.Transaction.$queryRawUnsafe<
    Array<{ category: string; type: string; amount: number | null }>
  >(
    `SELECT category, type, SUM(amount) as amount
     FROM "Transaction"
     WHERE userId = ? AND date(date) >= date(?) AND date(date) <= date(?)
     GROUP BY category, type
     ORDER BY category ASC`,
    userId,
    startDate,
    endDate
  );

  const categoryBreakdown: CategoryBreakdownPoint[] = rawCategoryBreakdown.map(
    (row) => ({
      category: row.category,
      amount: Number(row.amount) || 0,
      type: row.type as "INCOME" | "EXPENSE",
    })
  );

  const totalIncome = timeSeries.reduce((sum, point) => sum + point.income, 0);
  const totalExpense = timeSeries.reduce(
    (sum, point) => sum + point.expense,
    0
  );
  const netSavings = totalIncome - totalExpense;
  const savingsRate =
    totalIncome > 0
      ? Math.round((netSavings / totalIncome) * 100 * 100) / 100
      : 0;

  return {
    timeSeries,
    categoryBreakdown,
    summary: {
      totalIncome,
      totalExpense,
      netSavings,
      savingsRate,
    },
  };
};

import { HttpError } from "wasp/server";
import type { CreateTransaction } from "wasp/server/operations";
import type { Transaction } from "wasp/entities";

type CreateTransactionInput = {
  date: string;
  amount: number;
  type: "INCOME" | "EXPENSE";
  category: string;
  description: string;
};

export const createTransaction: CreateTransaction<
  CreateTransactionInput,
  Transaction
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const { date, amount, type, category, description } = args;

  return context.entities.Transaction.create({
    data: {
      date: new Date(date),
      amount,
      type,
      category,
      description,
      user: { connect: { id: context.user.id } },
    },
  });
};

import type { DbSeedFn } from "wasp/server";
import { sanitizeAndSerializeProviderData } from "wasp/server/auth";

const SEED_TRANSACTIONS = [
  {
    date: "2026-07-01",
    amount: 5000.0,
    type: "INCOME",
    category: "Sales",
    description: "Project payment",
  },
  {
    date: "2026-07-15",
    amount: 1200.0,
    type: "EXPENSE",
    category: "Marketing",
    description: "Ad campaign",
  },
  {
    date: "2026-07-20",
    amount: 800.0,
    type: "EXPENSE",
    category: "Software",
    description: "SaaS subscriptions",
  },
  {
    date: "2026-07-25",
    amount: 2500.0,
    type: "INCOME",
    category: "Investment",
    description: "Dividend payout",
  },
] as const;

export const seedData: DbSeedFn = async (prisma) => {
  const user = await prisma.user.create({
    data: {
      auth: {
        create: {
          identities: {
            create: {
              providerName: "username",
              providerUserId: "testuser",
              providerData: await sanitizeAndSerializeProviderData<"username">({
                hashedPassword: "password123",
              }),
            },
          },
        },
      },
    },
  });

  for (const transaction of SEED_TRANSACTIONS) {
    await prisma.transaction.create({
      data: {
        date: new Date(transaction.date),
        amount: transaction.amount,
        type: transaction.type,
        category: transaction.category,
        description: transaction.description,
        userId: user.id,
      },
    });
  }
};

